groups.push(['ДОПОЛНИТЕЛЬНО',['assignments','▦','Смены рабочих мест'],['payment-settings','₾','Способы оплаты'],['messages','✉','Уведомления'],['expense-templates','▤','Шаблоны расходов'],['supplier-orders','▧','Заказы поставщикам']]);
