const btn=(label,attrs='',cls='secondary')=>`<button class="${cls}" ${attrs}>${label}</button>`;
const opts=(items,value='',empty=false)=>`${empty?'<option value="">Не выбрано</option>':''}${items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('')}`;
