 if(page==='clients'){if(selectedClient){const c=state.clients.find(c=>c.id===selectedClient),visits=state.appointments.filter(a=>a.clientId===c.id),done=visits.filter(a=>a.status==='paid');return panel(esc(c.name),`<div class="padded"><p>${esc(c.phone)} · ${esc(c.source)}</p><p>${esc(c.note)||'Нет заметок'}</p><p>Теги: ${esc(c.tags)||'—'}</p><p>Email: ${esc(c.email)||'—'} · Поздних отмен: ${visits.filter(a=>a.lateCancellation).length}</p></div>${stats([['ВИЗИТОВ',done.length],['СРЕДНИЙ ЧЕК',money(done.length?sum(done,'amount')/done.length:0)],['БОНУСОВ НАЧИСЛЕНО',money(sum(done,'bonusEarned'))],['СТАТУС',c.blocked?'Блокировка':'Активен']])}${appointmentRows(visits)}`,btn('← К списку','data-page="clients"')+edit('clients',c.id));}
 const cs=state.clients.filter(c=>{const v=state.appointments.filter(a=>a.status==='paid'&&a.clientId===c.id),last=v.map(a=>a.date).sort().at(-1);return (c.name+' '+c.phone+' '+c.tags+' '+(c.email||'')).toLowerCase().includes(query.toLowerCase())&&(!sourceFilter||c.source===sourceFilter)&&(!tagFilter||c.tags.split(',').map(t=>t.trim()).includes(tagFilter))&&(!filter||filter==='blocked'&&c.blocked||filter==='regular'&&v.length>=2||filter==='potential'&&!v.length||filter==='lost'&&last&&last<addDays(today(),-180)||filter==='sleep'&&last&&last<addDays(today(),-60)&&last>=addDays(today(),-180));});return panel('Клиентская база',table(['Имя','Телефон','Теги / источник','Визиты','Последний визит','Средний чек',''],cs.map(c=>{const v=state.appointments.filter(a=>a.status==='paid'&&a.clientId===c.id);return [btn(esc(c.name),`data-client="${c.id}"`),esc(c.phone),`${esc(c.tags)}<small>${esc(c.source)}</small>`,v.length,v.map(a=>a.date).sort().at(-1)||'—',money(v.length?sum(v,'amount')/v.length:0),edit('clients',c.id)];})),`<input id="search" placeholder="Имя, телефон, email или тег" value="${esc(query)}"><select id="filter">${[['','Все'],['regular','Постоянные (2+ визита)'],['sleep','Спящие (60–179 дней)'],['lost','Потерянные (180+ дней)'],['potential','Без оплаченных визитов'],['blocked','Заблокированные']].map(([id,n])=>`<option value="${id}" ${filter===id?'selected':''}>${n}</option>`).join('')}</select>`+clientFilters()+add('clients','Клиент')+btn('Импорт CSV','data-page="import"')+btn('Экспорт CSV','data-export="clients"'));}
 if(page==='employees')return panel('Команда',`<div class="cards padded">${state.employees.map((e,i)=>`<article class="person panel"><span class="big-avatar color${i%3}">${esc(e.name[0])}</span><h2>${esc(e.name)}</h2><p>${esc(e.role)}</p><p class="muted">Начисление: ${e.commission}% от оплаченной суммы<br>${e.active?'Активен':'Не принимает записи'}</p>${edit('employees',e.id)}</article>`).join('')}</div>`,add('employees','Сотрудник'));
