function monthControl(){return `<input id="period" type="month" value="${period}" aria-label="Месяц">`;}
function employeeControl(){return `<select id="employee-filter" aria-label="Мастер"><option value="">Все мастера</option>${opts(state.employees,employee)}</select>`;}
function cashPanel(){const s=shift();return panel('Кассовая смена',`<div class="padded"><h2>${s?'В кассе: '+money(cashBalance(state)):'Смена закрыта'}</h2><p class="muted">${s?'Открыта '+s.date+' · На открытие '+money(s.opening):'Откройте смену перед приёмом оплаты.'}</p></div>`,s?btn('Внести / изъять','data-form="cash"')+btn('Закрыть смену','data-form="shift-close"','primary'):add('shift-open','Открыть смену'));}
