 if(page==='purchases'||active==='Партии')content=table(['Дата','Товар','Склад','Поставщик','Количество','Цена закупки','Остаток партии'],state.purchases.map(p=>[p.date,nameOf('products',p.productId),nameOf('warehouses',p.warehouseId),nameOf('suppliers',p.supplierId),p.qty,money(p.cost),p.remaining]));
 else if(active==='Типы продуктов')content=table(['Тип продукта',''],state.productTypes.map(t=>[esc(t.name),edit('productTypes',t.id)]));
 else if(page==='transfers'||active==='Движения'||active==='Перемещения')content=table(['Дата','Товар','Склад','Количество','Основание'],state.movements.filter(m=>page!=='transfers'&&active!=='Перемещения'||m.reason==='Перемещение').slice().reverse().map(m=>[m.date,nameOf('products',m.productId),nameOf('warehouses',m.warehouseId),m.qty,esc(m.reason)]));
 else if(active==='Поставщики')content=table(['Поставщик','Телефон','Примечание',''],state.suppliers.map(s=>[esc(s.name),esc(s.phone),esc(s.note),edit('suppliers',s.id)]));
 else if(active==='Склады')content=table(['Склад',''],state.warehouses.map(w=>[esc(w.name),edit('warehouses',w.id)]));
 else content=table(['Товар / бренд','Категория / штрихкод','Остаток','Порог','Цена продажи',''],state.products.filter(p=>(p.name+' '+p.brand+' '+p.sku).toLowerCase().includes(query.toLowerCase())).map(p=>[`${esc(p.name)}<small>${esc(p.brand)}</small>`,`${esc(p.category)}<small>${esc(p.sku)}</small>`,`${stock(state,p.id)} ${esc(p.unit)} ${stock(state,p.id)<=p.threshold?'<span class="badge">Мало</span>':''}`,p.threshold,money(p.price),edit('products',p.id)]));
