function importRows(){if(!csvImport)return [];const phoneOf=v=>String(v||'').replace(/\D/g,''),seen=new Set(state.clients.map(c=>phoneOf(c.phone)));return csvImport.rows.map((r,i)=>{const c=Object.fromEntries(['name','phone','email','note'].map(k=>[k,csvImport.mapping[k]===''?'':r[Number(csvImport.mapping[k])]||''])),phone=phoneOf(c.phone);let status=!c.name.trim()||!/^\d{7,15}$/.test(phone)?'Ошибка':seen.has(phone)?'Дубликат':'Новый';if(status==='Новый')seen.add(phone);return {...c,phone:'+'+phone,row:i+2,status};});}
function importWorkspace(){const rows=importRows();return panel('Перенос клиентов из DIKIDI / CSV',`<div class="padded"><p>Загрузите CSV, сопоставьте колонки и проверьте результат. До подтверждения данные не меняются.</p><input id="migration-file" type="file" accept=".csv,text/csv" aria-label="Файл клиентов"><p class="muted">UTF-8, запятая или точка с запятой. До 200 строк за один пакет. Телефоны должны включать код страны.</p>${csvImport?`<h3>${esc(csvImport.name)}</h3><div class="form-grid">${[['name','Имя'],['phone','Телефон'],['email','Email'],['note','Заметка']].map(([k,label])=>select('map-'+k,label,csvImport.headers.map((name,i)=>({id:String(i),name})),csvImport.mapping[k],true)).join('')}</div>${stats([['НОВЫХ',rows.filter(r=>r.status==='Новый').length],['ДУБЛИКАТОВ',rows.filter(r=>r.status==='Дубликат').length],['ОШИБОК',rows.filter(r=>r.status==='Ошибка').length]])}${table(['Строка','Имя','Телефон','Результат'],rows.map(r=>[r.row,esc(r.name),esc(r.phone),r.status]))}${btn('Импортировать новые записи','data-migration-commit '+(rows.some(r=>r.status==='Ошибка')||!rows.some(r=>r.status==='Новый')?'disabled':''),'primary')}`:''}</div>`)+notice('Существующие клиенты не перезаписываются. Это импорт файла, не синхронизация с DIKIDI. Для записей, услуг и мастеров нужен пример их выгрузки — поля и статусы нельзя надёжно угадать.')+panel('История пакетов',table(['Дата','Источник','Файл','Добавлено','Пропущено'],state.importBatches.map(b=>[b.date,esc(b.source),esc(b.fileName),b.added,b.skipped])));
}
function bindImportWorkspace(){document.querySelector('#migration-file')?.addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>500000)throw Error('Файл до 500 КБ');const text=await f.text(),first=text.split('\n')[0],delimiter=(first.match(/;/g)||[]).length>(first.match(/,/g)||[]).length?';':',',parsed=parseCSV(text,delimiter),headers=parsed.shift().map(h=>h.trim()),rows=parsed.filter(r=>r.some(v=>v.trim()));if(!rows.length||rows.length>200)throw Error('Нужно от 1 до 200 строк');const mapping={};for(const [k,regex] of [['name',/^(name|имя|фио|клиент)$/i],['phone',/телефон|phone/i],['email',/email|почта/i],['note',/note|замет|комментар/i]]){const i=headers.findIndex(h=>regex.test(h));mapping[k]=i<0?'':String(i);}csvImport={name:f.name,headers,rows,mapping};render();}catch(err){toast(err.message);}});
 for(const k of ['name','phone','email','note'])document.querySelector(`[name=map-${k}]`)?.addEventListener('change',e=>{csvImport.mapping[k]=e.target.value;render();});
 document.querySelector('[data-migration-commit]')?.addEventListener('click',async e=>{e.target.disabled=true;try{const rows=importRows();if(rows.some(r=>r.status==='Ошибка'))throw Error('Исправьте ошибки в файле или сопоставлении');await post('import-client-batch',{source:'DIKIDI / CSV',fileName:csvImport.name,clients:rows});csvImport=null;render();toast('Импорт завершён');}catch(err){toast(err.message);e.target.disabled=false;}});
}


